fs.writeFileSync(path.join(root,'admin','claude','index.html'),"<!doctype html><html lang=\"en\"><head><meta charset=\"utf-8\"><meta name=\"viewport\" content=\"width=device-width,initial-scale=1\"><meta name=\"robots\" content=\"noindex,nofollow,noarchive\"><title>Private AI Chat | USETOOLBENCH Admin</title><style>body{font:16px system-ui,sans-serif;background:#f3f5fa;color:#17243a;margin:0}main{max-width:850px;margin:24px auto;background:white;padding:24px;border-radius:16px;box-shadow:0 5px 20px #0001}input,textarea{font:inherit;box-sizing:border-box;width:100%;padding:12px;border:1px solid #bdc8d7;border-radius:8px;margin:8px 0}button{background:#244e92;color:white;border:0;border-radius:8px;padding:12px 18px;cursor:pointer;margin:6px}button:disabled{opacity:.5}#history{min-height:200px;max-height:55vh;overflow:auto;white-space:pre-wrap;overflow-wrap:anywhere;background:#f6f8fc;border-radius:10px;padding:16px}.entry{padding:10px;border-bottom:1px solid #dce4ed}.status{color:#a53a25}@media(max-width:600px){main{margin:8px;padding:14px}}</style></head><body><main><h1>Private Hugging Face AI Chat</h1><p>Admin only. Powered by the configured Hugging Face model, not official Anthropic Claude.</p><label for=\"token\">Admin access token</label><input id=\"token\" type=\"password\" autocomplete=\"off\" placeholder=\"Enter admin token\"><p>Token is held only in this tab and is not saved to browser storage.</p><div id=\"history\" aria-live=\"polite\">Start a private conversation.</div><label for=\"message\">Your message</label><textarea id=\"message\" rows=\"4\" maxlength=\"4000\" placeholder=\"Ask a question\"></textarea><button id=\"send\">Send</button><button id=\"clear\" type=\"button\">Clear conversation</button><p id=\"status\" class=\"status\" role=\"status\"></p></main><script>const history=[],box=document.getElementById('history'),status=document.getElementById('status'),send=document.getElementById('send');function draw(){box.replaceChildren();for(const m of history){const d=document.createElement('div');d.className='entry';const strong=document.createElement('strong');strong.textContent=m.role==='user'?'You: ':'Assistant: ';d.append(strong,document.createTextNode(m.content));box.append(d)}box.scrollTop=box.scrollHeight}document.getElementById('clear').onclick=()=>{history.length=0;box.textContent='Conversation cleared.';status.textContent=''};send.onclick=async()=>{const token=document.getElementById('token').value.trim(),message=document.getElementById('message').value.trim();if(!token||!message){status.textContent='Enter admin token and a message.';return}const next=[...history,{role:'user',content:message}].slice(-12);send.disabled=true;status.textContent='Waiting for Hugging Face…';try{const r=await fetch('https://usetoolbench-deals.onrender.com/api/admin/hf-chat',{method:'POST',headers:{'Content-Type':'application/json','Authorization':'Bearer '+token},body:JSON.stringify({messages:next})});const type=r.headers.get('content-type')||'';if(!type.includes('application/json'))throw Error('AI backend returned a non-JSON response (HTTP '+r.status+'). Please retry or check Render API routing.');const data=await r.json();if(!r.ok)throw Error(data.error||'Request failed ('+r.status+')');history.splice(0,history.length,...next,{role:'assistant',content:data.output});document.getElementById('message').value='';draw();status.textContent=''}catch(e){status.textContent=e.message}finally{send.disabled=false}};</script></body></html>");
