const sapModules=[["fi","FI – Financial Accounting","General ledger, accounts payable, accounts receivable, asset accounting and closing.","Post a supplier invoice: debit expense or inventory clearing as applicable, credit supplier."],["co","CO – Controlling","Cost centers, profit centers, internal orders, product costing and profitability analysis.","Assign an expense to a cost center and review actual versus plan."],["mm","MM – Materials Management","Purchasing, inventory management, material master and invoice verification.","Purchase requisition → purchase order → goods receipt → invoice verification."],["sd","SD – Sales and Distribution","Sales orders, pricing, delivery, billing and credit management.","Sales order → outbound delivery → goods issue → billing."],["pp","PP – Production Planning","BOM, routing, MRP, production orders and confirmations.","Run MRP, create a production order, issue components and receive finished goods."],["qm","QM – Quality Management","Inspection plans, inspection lots, results and usage decisions.","Record inspection results for a goods receipt and make a usage decision."],["pm","Asset Management (PM/EAM)","Equipment, functional locations, notifications and maintenance orders.","Create a maintenance notification and plan corrective maintenance."],["ewm","Extended Warehouse Management","Inbound and outbound warehouse processes, storage bins and warehouse tasks.","Receive goods, create a putaway task and confirm the destination bin."],["tm","Transportation Management","Freight planning, freight orders and settlement.","Plan transportation for outbound deliveries and create a freight order."],["ps","Project System","WBS elements, networks, budgeting and project settlement.","Create a WBS structure and assign project costs."],["aa","Asset Accounting (FI-AA)","Asset acquisition, depreciation, transfers and retirement.","Acquire an asset and review planned depreciation."],["treasury","Treasury and Risk Management","Cash management, financial instruments and risk analysis.","Review cash positions and forecast liquidity."],["gr","Group Reporting","Financial consolidation, intercompany elimination and group reporting.","Prepare consolidation data and eliminate intercompany balances."],["service","Service Management","Service contracts, service orders, execution and billing.","Create a service order and confirm work performed."],["aATP","Advanced Available-to-Promise","Product availability checks, allocation and backorder processing.","Check requested delivery quantities against available supply."],["mdg","Master Data Governance","Governance workflows, validation and master data quality.","Submit a business partner change request for approval."],["fiori","SAP Fiori","Role-based applications, launchpad and user experience.","Locate an authorized business app and review its filters."],["abap","ABAP and Extensibility","ABAP development, CDS views, RAP and clean-core extensions.","Define a read-only CDS view in an authorized development environment."],["basis","Basis and Security","System administration, authorizations, transports and monitoring.","Review a role assignment and transport request in a test system."],["analytics","Embedded Analytics","CDS analytical queries, KPIs and operational reporting.","Review a sales or inventory analytical report."],["hcm","HR and SuccessFactors Integration","Employee data and integration with HR solutions; deployment scope varies.","Review employee master integration requirements."],["grc","Governance, Risk and Compliance","Access risk analysis, segregation of duties and controls; separate solutions may be required.","Identify conflicting purchasing and payment permissions."]];
const sapLinks='<nav>'+sapModules.map(([slug,title])=>'<a href="/learn/sap-s4hana/'+slug.toLowerCase()+'/">'+esc(title)+'</a>').join('')+'</nav>';
page('learn/sap-s4hana','SAP S/4HANA Tutorials','Learn SAP S/4HANA functional modules, technical topics and integrated business processes.','<p>Scope and app availability vary by edition, release and license. These original introductory lessons are not official SAP training.</p><section class="panel">'+sapLinks+'</section>');
for(const [slug,title,desc,example] of sapModules){page('learn/sap-s4hana/'+slug.toLowerCase(),'SAP S/4HANA '+title,desc,'<p><a href="/learn/sap-s4hana/">All SAP S/4HANA modules</a></p><section class="panel"><h2>Overview</h2><p>'+esc(desc)+'</p><h2>Practical exercise</h2><p>'+esc(example)+'</p><p>Practice only in an authorized training system. Exact applications and configuration depend on your edition.</p></section>'+sapLinks);}
const b1Topics=[["query-manager","SQL Query Manager","Open Tools → Queries → Query Generator or Query Manager (menu availability depends on authorization). Create a query, execute it, save it in a category and assign authorized users. Use [%0] and [%1] for date parameters.","SELECT DocNum, DocDate, CardCode, CardName, DocTotal FROM ORDR WHERE DocDate >= CONVERT(date, '[%0]') AND DocDate <= CONVERT(date, '[%1]') AND CANCELED = 'N';"],["sales","Sales and A/R","Quotation → Sales Order → Delivery → A/R Invoice → Incoming Payment. Delivery normally debits COGS and credits inventory; invoice debits customer and credits revenue and output tax.","SELECT H.DocNum,H.DocDate,H.CardName,L.ItemCode,L.Quantity,L.LineTotal FROM OINV H JOIN INV1 L ON H.DocEntry=L.DocEntry WHERE H.CANCELED='N';"],["purchase","Purchasing and A/P","Purchase Request → Purchase Order → GRPO → A/P Invoice → Outgoing Payment. Under perpetual inventory, GRPO normally debits inventory and credits allocation; invoice clears allocation and credits vendor, subject to tax and differences.","SELECT H.DocNum,H.CardName,L.ItemCode,L.OpenQty FROM OPOR H JOIN POR1 L ON H.DocEntry=L.DocEntry WHERE H.CANCELED='N' AND L.LineStatus='O';"],["inventory","Inventory Management","Item master, warehouses, stock transfers, goods receipts and issues. OnHand is physical stock; committed and ordered quantities affect availability.","SELECT I.ItemCode,I.ItemName,W.WhsCode,W.OnHand,W.IsCommited,W.OnOrder FROM OITM I JOIN OITW W ON I.ItemCode=W.ItemCode;"],["finance","Financial Accounting","Journal entries, chart of accounts, reconciliations, receivables and payables. Each journal entry balances debits and credits.","SELECT H.TransId,H.RefDate,L.Account,L.ShortName,L.Debit,L.Credit FROM OJDT H JOIN JDT1 L ON H.TransId=L.TransId;"],["production","Production and MRP","BOM → Production Order → Issue for Production → Receipt from Production → Close. Actual WIP and finished goods postings depend on valuation and configuration.","SELECT H.DocNum,H.ItemCode,H.PlannedQty,H.CmpltQty,H.Status FROM OWOR H WHERE H.Status IN ('P','R');"],["business-partners","Business Partners","Maintain customer and vendor master data, payment terms and addresses.","SELECT CardCode,CardName,CardType,Balance FROM OCRD WHERE CardType IN ('C','S');"],["banking","Banking and Payments","Incoming payments normally debit bank and credit customer; outgoing payments debit vendor and credit bank. Reconciliation matches open transactions.","SELECT DocNum,DocDate,CardCode,DocTotal FROM OVPM WHERE Canceled='N';"],["service","Service Management","Service calls, equipment cards and service contracts.","SELECT callID,customer,subject,status FROM OSCL;"],["fixed-assets","Fixed Assets","Asset acquisition, depreciation and retirement. Depreciation normally debits depreciation expense and credits accumulated depreciation.","SELECT ItemCode,ItemName FROM OITM WHERE AssetItem='Y';"],["crm","CRM and Opportunities","Track prospects, activities and sales opportunities.","SELECT CardCode,CardName FROM OCRD WHERE CardType='L';"],["fms","Formatted Search (FMS)","Assign a saved query to a field using user-defined values. Form references depend on the actual form and item IDs; verify using System Information.","SELECT ItemName FROM OITM WHERE ItemCode = $[$38.1.0];"],["transaction-notification","Transaction Notification","SBO_SP_TransactionNotification validates transactions before commit. Test changes in a sandbox; never modify SAP business tables directly. Example below is a read-only diagnostic, not a complete stored procedure.","SELECT DocEntry,DocNum,CardCode FROM ORDR WHERE CardCode IS NULL;"],["crystal-reports","Crystal Reports","Create reports using supported data connections, parameters and layouts. Test the report against a non-production database.","SELECT H.DocNum,H.CardName,L.Dscription,L.Quantity FROM OQUT H JOIN QUT1 L ON H.DocEntry=L.DocEntry;"],["query-library","SQL Query Library","Use read-only SELECT queries. Avoid direct UPDATE, INSERT or DELETE against SAP application tables. Validate results against standard reports.","SELECT T0.DocNum,T0.DocDate,T0.CardName,T1.ItemCode,T1.Quantity,T1.LineTotal FROM OQUT T0 INNER JOIN QUT1 T1 ON T0.DocEntry=T1.DocEntry WHERE T0.CANCELED='N';"],["administration","Administration and Authorizations","Company settings, users, roles, approvals, numbering series and backup coordination. Use authorized administration screens.","SELECT Series,SeriesName,ObjectCode FROM NNM1;"]];
const b1ExtraLinks={sales:[['Sales Cycle: Quotation → Incoming Payment','/learn/sap-b1/sales-cycle/']],purchase:[['Purchase Cycle: PR → Outgoing Payment','/learn/sap-b1/purchase-cycle/']],'query-manager':[['SQL Practice Playground','/learn/sap-b1/sql-practice/']]};
const b1Nav='<nav class="b1-module-nav" aria-label="SAP Business One modules">'+b1Topics.map(([slug,title])=>'<section class="b1-module-card"><a class="b1-module-link" href="/learn/sap-b1/'+slug+'/">'+esc(title)+'<span aria-hidden="true">›</span></a>'+(b1ExtraLinks[slug]||[]).map(([label,url])=>'<a class="b1-sub-link" href="'+url+'">'+esc(label)+'</a>').join('')+'</section>').join('')+'</nav>';
const b1Landing='<style>.b1-course{max-width:1100px;margin:auto}.b1-module-nav{display:grid!important;grid-template-columns:repeat(auto-fit,minmax(min(100%,300px),1fr));gap:14px!important}.b1-module-card{min-width:0;border:1px solid #cbd5e1;border-radius:12px;background:#fff;padding:14px;display:flex;flex-direction:column;gap:8px}.b1-module-link{display:flex!important;align-items:center;justify-content:space-between;gap:10px;padding:10px!important;text-decoration:none!important;font-weight:700;color:#174b38!important;overflow-wrap:anywhere}.b1-sub-link{display:block!important;margin:0 8px;padding:12px!important;border-top:1px solid #e2e8f0;color:#2563eb!important;text-decoration:underline!important;overflow-wrap:anywhere;line-height:1.5}.b1-module-link span{font-size:22px}@media(max-width:700px){.b1-module-nav{grid-template-columns:minmax(0,1fr)!important}.b1-module-card{padding:12px}}</style><div class="b1-course"><p>Choose a module below. Its related document flows and lessons are listed directly underneath that module.</p><h2>SAP B1 Modules</h2>'+b1Nav+'</div>';
