 sales:[['quotation','Sales Quotation','Prepare a customer offer and verify prices, validity and tax.','OQUT / QUT1'],['sales-order','Sales Order','Copy an accepted quotation; check committed quantity and delivery date.','ORDR / RDR1'],['delivery','Delivery','Copy open sales order rows and verify warehouse and issued stock.','ODLN / DLN1'],['ar-invoice','A/R Invoice','Copy delivery, validate GST and customer receivable.','OINV / INV1'],['incoming-payment','Incoming Payment','Apply the receipt to open invoices and verify the customer balance.','ORCT / RCT2']],
 purchase:[['purchase-request','Purchase Request','Raise an internal requirement; no accounting entry normally occurs.','OPRQ / PRQ1'],['purchase-order','Purchase Order','Choose vendor and terms; copy from purchase request when appropriate.','OPOR / POR1'],['grpo','Goods Receipt PO','Receive ordered items and inspect inventory and clearing postings.','OPDN / PDN1'],['ap-invoice','A/P Invoice','Recognize vendor liability and applicable input tax.','OPCH / PCH1'],['outgoing-payment','Outgoing Payment','Apply payment to the vendor invoice and verify clearing.','OVPM / VPM2']],
 inventory:[['item-master','Item Master Data','Review inventory item settings, valuation and UoM.','OITM'],['warehouse','Warehouse Stock','Compare on-hand, committed, ordered and available stock.','OITW'],['stock-transfer','Inventory Transfer','Transfer stock between warehouses with approval.','OWTR / WTR1'],['stock-count','Inventory Counting','Count and reconcile physical quantities.','OINC / INC1']],
 production:[['bom','Bill of Materials','Define parent item, components and required quantities.','OITT / ITT1'],['production-order','Production Order','Create, release and monitor a manufacturing order.','OWOR / WOR1'],['issue','Issue for Production','Issue components to WIP and check consumption.','OIGE / IGE1'],['receipt','Receipt from Production','Receive finished goods and review WIP valuation.','OIGN / IGN1']],
 finance:[['chart-of-accounts','Chart of Accounts','Review G/L structure and account determination.','OACT'],['journal-entry','Journal Entry','Post balanced debits and credits with correct dates.','OJDT / JDT1'],['reconciliation','Internal Reconciliation','Match open transactions and verify remaining balances.','OITR / ITR1'],['financial-reports','Financial Reports','Review trial balance, P&L and balance sheet.','OACT / JDT1']],
 banking:[['incoming','Incoming Payments','Receive customer payments against invoices.','ORCT / RCT2'],['outgoing','Outgoing Payments','Settle vendor invoices through bank or cash.','OVPM / VPM2'],['bank-reconciliation','Bank Reconciliation','Match bank statements to recorded transactions.','Banking reconciliation data']],
 'business-partners':[['customer','Customer Master','Create customer master and verify terms and tax details.','OCRD'],['vendor','Vendor Master','Create vendor master and validate payment terms.','OCRD'],['addresses','BP Addresses','Maintain bill-to and ship-to addresses.','CRD1']],
 crm:[['leads','Leads','Record prospect details and activities.','OCRD'],['opportunities','Opportunities','Manage stages, expected amounts and closing dates.','OOPR'],['activities','Activities','Schedule and complete customer follow-ups.','OCLG']],
 service:[['service-call','Service Calls','Record customer issues and follow resolution.','OSCL'],['equipment','Equipment Cards','Track installed customer equipment.','OINS'],['contracts','Service Contracts','Review service coverage and expiry.','OCTR']],
 'fixed-assets':[['asset-master','Asset Master','Review acquisition and depreciation parameters.','OITM'],['capitalization','Capitalization','Post approved asset acquisition.','Asset transactions'],['depreciation','Depreciation','Review depreciation run and G/L postings.','Asset transactions']],
 'query-manager':[['create-query','Create SQL Query','Write a read-only SELECT and test output.','SQL Server'],['parameters','Query Parameters','Use SAP Query Manager parameters correctly.','[%0] / [%1]'],['permissions','Query Access','Save query and assign access to authorized users.','Query Manager']],
 fms:[['create-fms','Create Formatted Search','Bind a saved query to a field.','Query Manager'],['test-fms','Test Field Mapping','Verify form item IDs and query execution.','System Information']],
 'transaction-notification':[['validation','Validation Logic','Review transaction types and object types.','SBO_SP_TransactionNotification'],['test-validation','Test Safely','Test errors and successful postings in a test database.','SQL Server']],
 'crystal-reports':[['design','Design Layout','Build an approved document layout.','Crystal Reports'],['parameters','Report Parameters','Verify document parameters and data source.','Crystal Reports'],['preview','Preview and Print','Check runtime, preview and assigned layouts.','Report and Layout Manager']],
 'query-library':[['sales-reports','Sales Reports','Validate open sales and invoice queries.','ORDR / OINV'],['purchase-reports','Purchase Reports','Validate PO, GRPO and invoice queries.','OPOR / OPDN / OPCH'],['inventory-reports','Inventory Reports','Compare stock with SAP standard reports.','OITM / OITW']],
 administration:[['company-settings','Company Settings','Review posting periods, localization and document numbering.','OADM / NNM1'],['users','Users and Authorizations','Grant minimum necessary access and test it.','OUSR'],['approvals','Approval Procedures','Review approval stages and triggers.','Approval setup']]
