page('api-tester','API Tester – REST Client','Test HTTP APIs with methods, headers, bearer authentication and JSON responses directly in your browser.',"<section style=\"display:grid;gap:12px\"><p>Send HTTP requests directly from your browser to APIs you are authorized to use. Browser CORS rules apply. Credentials are not saved.</p><label>Method <select id=\"api-method\"><option>GET</option><option>POST</option><option>PUT</option><option>PATCH</option><option>DELETE</option><option>HEAD</option><option>OPTIONS</option></select></label><label>Request URL <input id=\"api-url\" type=\"url\" placeholder=\"https://api.example.com/resource\" style=\"width:100%\"></label><label>Headers (JSON object)<textarea id=\"api-headers\" rows=\"4\" style=\"width:100%\" placeholder='{\"Content-Type\":\"application/json\"}'></textarea></label><label>Bearer token (optional)<input id=\"api-token\" type=\"password\" autocomplete=\"off\" style=\"width:100%\"></label><label>Request body<textarea id=\"api-body\" rows=\"7\" style=\"width:100%\"></textarea></label><div><button id=\"api-send\">Send request</button> <button id=\"api-copy\">Copy response</button></div><strong id=\"api-status\" role=\"status\">Ready</strong><h2>Response headers</h2><pre id=\"api-response-headers\" style=\"white-space:pre-wrap\"></pre><h2>Response body</h2><pre id=\"api-response\" style=\"white-space:pre-wrap;overflow-wrap:anywhere\"></pre></section><script>(()=>{const el=id=>document.getElementById(id);el('api-send').onclick=async()=>{const button=el('api-send');button.disabled=true;el('api-response').textContent='';el('api-response-headers').textContent='';el('api-status').textContent='Sending…';const start=performance.now();const controller=new AbortController();const timer=setTimeout(()=>controller.abort(),30000);try{const url=new URL(el('api-url').value);if(!['https:','http:'].includes(url.protocol)||url.username||url.password)throw Error('Enter an HTTP(S) URL without embedded credentials');const method=el('api-method').value;const raw=JSON.parse(el('api-headers').value||'{}');if(!raw||typeof raw!=='object'||Array.isArray(raw))throw Error('Headers must be a JSON object');const headers=new Headers(raw);if(el('api-token').value){if(url.protocol!=='https:')throw Error('Use HTTPS for bearer tokens');headers.set('Authorization','Bearer '+el('api-token').value)}const response=await fetch(url,{method,headers,body:['GET','HEAD'].includes(method)?undefined:el('api-body').value||undefined,credentials:'omit',redirect:'error',signal:controller.signal});el('api-status').textContent=response.status+' '+response.statusText+' · '+Math.round(performance.now()-start)+' ms';el('api-response-headers').textContent=Array.from(response.headers).map(x=>x.join(': ')).join(String.fromCharCode(10));const reader=response.body?.getReader();let out='',bytes=0;const decoder=new TextDecoder();if(reader){while(true){const {done,value}=await reader.read();if(done)break;bytes+=value.length;if(bytes>1000000){await reader.cancel();out+=' [Response truncated at 1 MB]';break}out+=decoder.decode(value,{stream:true})}out+=decoder.decode()}try{out=JSON.stringify(JSON.parse(out),null,2)}catch{}el('api-response').textContent=out}catch(e){el('api-status').textContent='Request failed: '+e.message+' (check URL, CORS, HTTPS or timeout)'}finally{clearTimeout(timer);button.disabled=false}};el('api-copy').onclick=async()=>{try{await navigator.clipboard.writeText(el('api-response').textContent);el('api-status').textContent+=' · Copied'}catch{el('api-status').textContent+=' · Copy unavailable'}}})();</script>");
