page('file-size-reduce','File Size Reduce','Compress images or archive any file format with ZIP compression.',"<p>Reduce JPEG, PNG and WebP images in their original format, or compress any file into a ZIP archive. Already compressed files may not shrink.</p><label>Choose files <input id=\"fs-files\" type=\"file\" multiple></label><label>Compression <select id=\"fs-level\"><option value=\"0.85\">Low</option><option value=\"0.65\" selected>Medium</option><option value=\"0.4\">High</option><option value=\"0.2\">Maximum</option></select></label><label>Mode <select id=\"fs-mode\"><option value=\"auto\">Native image compression / ZIP fallback</option><option value=\"zip\">ZIP archive (all formats)</option></select></label><label>Target KB (images, optional) <input id=\"fs-target\" type=\"number\" min=\"1\" placeholder=\"Optional\"></label><button id=\"fs-run\">Reduce file size</button><div id=\"fs-results\" aria-live=\"polite\"></div><script type=\"module\" src=\"/file-size-reduce.mjs\"></script>",'tool');
fs.writeFileSync(path.join(root,'file-size-reduce.mjs'),"const $=id=>document.getElementById(id);const files=$('fs-files'),out=$('fs-results'),run=$('fs-run');let urls=[];const fmt=n=>n.toLocaleString()+' bytes';async function image(f,q,target){const bmp=await createImageBitmap(f);try{const c=document.createElement('canvas');let scale=1,b;for(let i=0;i<12;i++){c.width=Math.max(1,Math.round(bmp.width*scale));c.height=Math.max(1,Math.round(bmp.height*scale));c.getContext('2d').drawImage(bmp,0,0,c.width,c.height);b=await new Promise(resolve=>c.toBlob(resolve,f.type,q));if(!b||b.type!==f.type)throw Error('Native format not supported by browser');if((!target&&b.size<f.size)||(target&&b.size<=target))break;scale*=0.8;q=Math.max(.15,q*.9)}return b.size<f.size?b:f}finally{bmp.close()}}async function zip(f,q){const {zipSync}=await import('https://cdn.jsdelivr.net/npm/fflate@0.8.2/esm/browser.js');return new Blob([zipSync({[f.name]:new Uint8Array(await f.arrayBuffer())},{level:q<.5?9:6})],{type:'application/zip'})}run.onclick=async()=>{if(!files.files.length){out.textContent='Choose files first.';return}run.disabled=true;urls.forEach(URL.revokeObjectURL);urls=[];out.replaceChildren();try{for(const f of files.files){const row=document.createElement('p');out.append(row);row.textContent=f.name+' — processing…';try{if(f.size>100*1024*1024)throw Error('100 MB per file limit');const q=Number($('fs-level').value),target=Number($('fs-target').value)*1024;let b,name=f.name,native=$('fs-mode').value==='auto'&&['image/jpeg','image/png','image/webp'].includes(f.type);if(native){b=await image(f,q,target)}else{b=await zip(f,q);name=f.name+'.zip'}if(b.size>=f.size){row.textContent=f.name+' — no size reduction available. Original retained.';b=f;name=f.name}else row.textContent=f.name+' — '+fmt(f.size)+' → '+fmt(b.size)+' ('+((1-b.size/f.size)*100).toFixed(1)+'% smaller). '+(native&&target&&b.size>target?'Target not reached. ':'');const a=document.createElement('a');a.href=URL.createObjectURL(b);urls.push(a.href);a.download=name;a.textContent=' Download '+name;row.append(a)}catch(e){row.textContent=f.name+' — '+e.message}}}finally{run.disabled=false}};");
page('pdf-to-word','PDF to Word','Convert selectable PDF text into editable DOCX.',"<p>Extract selectable PDF text into an editable Word document. Layout and scanned text are not preserved.</p><input id=\"convert-file\" type=\"file\" accept=\".pdf\"><button id=\"convert-run\">Convert and download</button><p id=\"convert-status\" aria-live=\"polite\"></p><script type=\"module\" src=\"/pdf-to-word.mjs\"></script>",'tool');
