fs.writeFileSync(path.join(root,'pdf-to-word.mjs'),"const f=document.getElementById('convert-file'),b=document.getElementById('convert-run'),s=document.getElementById('convert-status');function download(blob,name){const a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download=name;a.textContent='Download '+name;s.replaceChildren(a);a.click()}b.onclick=async()=>{if(!f.files[0]){s.textContent='Choose a file first';return}b.disabled=true;s.textContent='Converting…';try{const file=f.files[0];const p=await import('https://cdn.jsdelivr.net/npm/pdfjs-dist@4.10.38/build/pdf.min.mjs');p.GlobalWorkerOptions.workerSrc='https://cdn.jsdelivr.net/npm/pdfjs-dist@4.10.38/build/pdf.worker.min.mjs';const d=await p.getDocument({data:new Uint8Array(await file.arrayBuffer())}).promise;const {Document,Paragraph,Packer}=await import('https://cdn.jsdelivr.net/npm/docx@9.5.1/+esm');const children=[];for(let i=1;i<=d.numPages;i++){const t=await (await d.getPage(i)).getTextContent();children.push(new Paragraph({text:t.items.map(x=>x.str||'').join(' '),pageBreakBefore:i>1}))}if(!children.length)throw Error('No pages');const blob=await Packer.toBlob(new Document({sections:[{children}]}));download(blob,file.name.replace(/\\.[^.]+$/,'')+'.docx');}catch(e){s.textContent=e.message}finally{b.disabled=false}};");
fs.writeFileSync(path.join(root,'jpg-to-png.mjs'),"const f=document.getElementById('convert-file'),b=document.getElementById('convert-run'),s=document.getElementById('convert-status');function download(blob,name){const a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download=name;a.textContent='Download '+name;s.replaceChildren(a);a.click()}b.onclick=async()=>{if(!f.files[0]){s.textContent='Choose a file first';return}b.disabled=true;s.textContent='Converting…';try{const file=f.files[0];const im=await createImageBitmap(file),c=document.createElement('canvas');c.width=im.width;c.height=im.height;c.getContext('2d').drawImage(im,0,0);im.close();const blob=await new Promise(r=>c.toBlob(r,'image/png'));if(!blob)throw Error('Conversion failed');download(blob,file.name.replace(/\\.[^.]+$/,'')+'.png');}catch(e){s.textContent=e.message}finally{b.disabled=false}};");
