for(const [slug,title,kb,w,h] of photoPresets){page(slug,title,'Free online '+title+'. Resize JPG photos locally in your browser with custom dimensions and file size.','<label>Choose image<input id="photo-input" type="file" accept="image/*"></label><label>Maximum KB<input id="photo-kb" type="number" min="1" max="10000" value="'+kb+'"></label><label>Width in pixels (0 = automatic)<input id="photo-w" type="number" min="0" max="6000" value="'+w+'"></label><label>Height in pixels (0 = automatic)<input id="photo-h" type="number" min="0" max="6000" value="'+h+'"></label><button id="photo-go">Resize and compress</button><p id="photo-result" role="status"></p><a id="photo-download" hidden>Download JPG</a><h2>How to use</h2><p>Choose a photo, set the maximum size and dimensions, then download the result. When both dimensions are specified, the image is center cropped. Check the preview and your application requirements before submitting.</p><img id="photo-preview" alt="Resized photo preview" hidden style="max-width:100%;max-height:300px"><h2>Frequently asked questions</h2><h3>Is my photo uploaded?</h3><p>No. Processing happens in your browser.</p><h3>Will the result be exactly the selected size?</h3><p>The tool aims for a file at or below the limit. Very small targets may require lower resolution or may not be achievable at fixed dimensions.</p><script type="module" src="/photo-size-tools.mjs"></script>','tool');}
fs.writeFileSync(path.join(root,'photo-size-tools.mjs'),`const el=id=>document.getElementById(id);let url;el('photo-go').onclick=async()=>{const f=el('photo-input').files[0],out=el('photo-result'),link=el('photo-download'),preview=el('photo-preview');link.hidden=true;preview.hidden=true;if(!f){out.textContent='Choose an image first';return}const target=Number(el('photo-kb').value)*1024,w=Number(el('photo-w').value),h=Number(el('photo-h').value);if(!Number.isFinite(target)||target<1024||target>10240000||![w,h].every(n=>Number.isInteger(n)&&n>=0&&n<=6000)){out.textContent='Enter valid size and dimensions';return}try{out.textContent='Processing…';const img=await createImageBitmap(f);const canvas=document.createElement('canvas'),ctx=canvas.getContext('2d');let width=w||Math.round(h?img.width*h/img.height:img.width),height=h||Math.round(w?img.height*w/img.width:img.height);let blob;for(let j=0;j<16;j++){canvas.width=Math.max(1,width);canvas.height=Math.max(1,height);ctx.fillStyle='white';ctx.fillRect(0,0,width,height);const scale=Math.max(width/img.width,height/img.height);ctx.drawImage(img,(width-img.width*scale)/2,(height-img.height*scale)/2,img.width*scale,img.height*scale);for(let q=.95;q>=.05;q-=.1){blob=await new Promise(resolve=>canvas.toBlob(resolve,'image/jpeg',q));if(blob&&blob.size<=target)break}if(blob&&blob.size<=target)break;if(w||h)break;width=Math.max(1,Math.floor(width*.8));height=Math.max(1,Math.floor(height*.8))}img.close();if(!blob||blob.size>target){out.textContent='Cannot reach target with these dimensions. Increase KB or reduce dimensions.';return}if(url)URL.revokeObjectURL(url);url=URL.createObjectURL(blob);link.href=url;link.download=f.name.replace(/\\.[^.]+$/,'')+'.jpg';link.hidden=false;preview.src=url;preview.hidden=false;out.textContent=(blob.size/1024).toFixed(2)+' KB · '+canvas.width+' × '+canvas.height+' pixels'}catch(e){out.textContent='Unable to process this image. Try a JPG or PNG.'}};`);


page('file-size-guide','Reduce PDF and Image File Size Online','Learn how to reduce PDF and JPG file sizes to 20KB, 50KB, 100KB, 200KB or 500KB for online applications.','<h2>Choose the right file size tool</h2><p>Check the upload limit and required format before resizing a document. A smaller file is useful only if the result remains readable.</p><ul><li><a href="/resize-image-to-20kb/">Resize JPG image to 20KB</a> for small signature uploads.</li><li><a href="/resize-image-to-50kb/">Resize photo to 50KB</a> for application forms.</li><li><a href="/resize-image-to-100kb/">Reduce image to 100KB</a> for larger photo uploads.</li><li><a href="/compress-pdf/">Compress PDF</a> for PDF limits such as 100KB, 200KB, 300KB and 500KB. Check the actual result; a specific limit is not guaranteed.</li><li><a href="/passport-size-photo-maker/">Passport size photo maker</a> with custom dimensions.</li><li><a href="/signature-resizer/">Signature resizer</a> with custom dimensions.</li></ul><h2>How to reduce a PDF file size</h2><p>Choose a compression setting, download the result and inspect every page. Raster compression may remove selectable text. Keep your original document. If the result is too large, try a lower resolution or split the document if the receiving portal permits multiple files.</p><h2>How to reduce JPG size without cropping</h2><p>Leave the width and height at zero to preserve the aspect ratio in the image size tools. Set the file size limit and inspect the resulting preview before downloading.</p><h2>Online application requirements</h2><p>Photo dimensions and file limits vary by exam, agency and year. Always follow the current official application instructions rather than assuming a universal size.</p>','tool');

/* SEO post-build: canonical sitemap inventory, crawlable homepage and page metadata. */
// Rebuild sitemap from pages actually emitted by the build. This avoids stale
// URLs, missing newly added tools and accidentally publishing the admin page.
const discoverPages=(dir,relative='')=>{
 const pages=[];
 for(const entry of fs.readdirSync(dir,{withFileTypes:true})){
  if(entry.isDirectory()){
   if(entry.name==='admin')continue;
   pages.push(...discoverPages(path.join(dir,entry.name),relative+entry.name+'/'));
  }else if(entry.name==='index.html')pages.push(base+'/'+relative);
 }
 return pages;
};
const discoveredUrls=[...new Set(discoverPages(root))].sort((a,b)=>a===base+'/'?-1:b===base+'/'?1:a.localeCompare(b));
fs.writeFileSync(path.join(root,'sitemap.xml'),'<?xml version="1.0" encoding="UTF-8"?>\\n<urlset xmlns="http://www.sitemaps.org/schemas/sitemap/0.9">\\n'+discoveredUrls.map(u=>'  <url><loc>'+u+'</loc></url>').join('\\n')+'\\n</urlset>\\n');
const seoUrls=[...fs.readFileSync(path.join(root,'sitemap.xml'),'utf8').matchAll(/<loc>([^<]+)<\/loc>/g)].map(m=>m[1]);
const seoUnique=[...new Set(seoUrls)];
const seoPages=seoUnique.map(url=>{
 const route=new URL(url).pathname;
 const file=path.join(root,route.replace(/^\//,''),'index.html');
 if(!fs.existsSync(file)) throw new Error('Sitemap target missing: '+url);
 const html=fs.readFileSync(file,'utf8');
 const title=(html.match(/<title>(.*?)<\/title>/s)||[])[1]||route;
 return {url,route,file,title,html};
});
const escSEO=s=>s.replace(/&/g,'&amp;').replace(/"/g,'&quot;').replace(/</g,'&lt;');
for(const p of seoPages){
 let html=p.html;
 const canonical='<link rel="canonical" href="'+p.url+'">';
 html=html.replace(/<link\s+rel="canonical"[^>]*>/gi,'');
 const type=p.route==='/'?'WebSite':p.route.startsWith('/learn/')?'LearningResource':'WebPage';
 if(type==='LearningResource') html=html.replace(/<script type="application\/ld\+json">[^<]*<\/script>/g,'');
 const schema={'@context':'https://schema.org','@type':type,name:p.title.replace(/ \| USETOOLBENCH$/,''),url:p.url,inLanguage:'en-IN'};
 const meta=canonical+'<meta name="robots" content="index,follow,max-image-preview:large">'+(!html.includes('property="og:url"')?'<meta property="og:url" content="'+p.url+'">':'')+(!html.includes('property="og:type"')?'<meta property="og:type" content="website">':'')+'<script type="application/ld+json">'+JSON.stringify(schema).replace(/</g,'\\u003c')+'</script>';
 html=html.replace('</head>',meta+'</head>');
 if(p.route==='/'){
 const directory='<section><h2>Explore all calculators, PDF tools and tutorials</h2><ul>'+seoPages.filter(x=>x.route!=='/').map(x=>'<li><a href="'+x.route+'">'+escSEO(x.title.replace(/ \| USETOOLBENCH$/,''))+'</a></li>').join('')+'</ul></section>';
 html=html.replace('</main>',directory+'</main>');
 }
 fs.writeFileSync(p.file,html);
}
fs.writeFileSync(path.join(root,'sitemap.xml'),'<?xml version="1.0" encoding="UTF-8"?><urlset xmlns="http://www.sitemaps.org/schemas/sitemap/0.9">'+seoUnique.map(url=>'<url><loc>'+url+'</loc></url>').join('')+'</urlset>');
console.log('SEO validated '+seoUnique.length+' sitemap targets.');

/* Global language navigation: translation is requested only after visitor selection. */
const languageWidget = function(){
 const codes="af sq am ar hy as ay az bm eu be bn bho bs bg ca ceb zh-CN zh-TW co hr cs da dv doi nl en eo et ee fi fr fy gl ka de el gn gu ht ha haw he hi hmn hu is ig ilo id ga it ja jv kn kk km rw gom ko kri ku ckb ky lo la lv ln lt lg lb mk mai mg ms ml mt mi mr mni-Mtei lus mn my ne no ny or om ps fa pl pt pa qu ro ru sm sa gd nso sr st sn sd si sk sl so es su sw sv tl tg ta tt te th ti ts tr tk ak uk ur ug uz vi cy xh yi yo zu".split(" ");
 const host=document.getElementById("global-language-picker");if(!host)return;
 const select=host.querySelector("select"),names=new Intl.DisplayNames(["en"],{type:"language"});
 for(const code of codes.sort((a,b)=>(names.of(a)||a).localeCompare(names.of(b)||b))){const option=document.createElement("option");option.value=code;option.textContent=(names.of(code)||code)+" ("+code+")";select.append(option);}
 select.value="en";
 host.querySelector("button").addEventListener("click",()=>{if(select.value==="en")return;const url=new URL("https://translate.google.com/translate");url.searchParams.set("sl","en");url.searchParams.set("tl",select.value);url.searchParams.set("u","https://usetoolbench.in"+location.pathname);window.open(url.href,"_blank","noopener,noreferrer");});
};
