h=h.replace('</head>','<style>#live-layer span{position:absolute;white-space:nowrap;color:transparent;background:#66bfff25;line-height:1;cursor:text;user-select:text;overflow:hidden}#live-layer span::selection{background:#258affaa;color:white}#live-layer span:hover{outline:1px solid #258aff}#live-stage:has(img:not([src])){display:none}</style></head>');
h=h.replace('</body>', '<script>(()=>{const $=id=>document.getElementById(id),img=$("live-image"),layer=$("live-layer"),file=$("file"),status=$("live-status");let url="",words=[],generation=0,selected="";function render(){layer.replaceChildren();const w=img.naturalWidth,h=img.naturalHeight;if(!w||!h)return;for(const word of words){const b=word.bbox;if(!b||!word.text.trim())continue;const span=document.createElement("span");span.textContent=word.text+" ";span.style.left=100*b.x0/w+"%";span.style.top=100*b.y0/h+"%";span.style.width=100*(b.x1-b.x0)/w+"%";span.style.height=100*(b.y1-b.y0)/h+"%";span.style.fontSize=Math.max(8,(b.y1-b.y0)*img.clientWidth/w*.85)+"px";layer.append(span)}}file.addEventListener("change",()=>{generation++;words=[];selected="";layer.replaceChildren();if(url)URL.revokeObjectURL(url);if(file.files[0]){url=URL.createObjectURL(file.files[0]);img.src=url}else img.removeAttribute("src")});img.addEventListener("load",render);new ResizeObserver(render).observe(img);$("run").onclick=async()=>{const f=file.files[0];if(!f)return;const g=++generation;$("run").disabled=true;status.textContent="Recognizing text on photo…";try{const result=await Tesseract.recognize(f,"eng");if(g!==generation)return;words=result.data.words||[];$("out").value=result.data.text;render();status.textContent=words.length?"Long press or drag to select text on the image.":"No text detected. Try a clearer photo."}catch(e){status.textContent="Recognition failed. Try again."}finally{$("run").disabled=false}};document.addEventListener("selectionchange",()=>{const s=getSelection();if(s&&s.anchorNode&&layer.contains(s.anchorNode)&&s.toString().trim())selected=s.toString().trim()});async function copy(t){if(!t){status.textContent="Select text first.";return}try{await navigator.clipboard.writeText(t);status.textContent="Copied to clipboard."}catch(e){status.textContent="Clipboard unavailable. Select text and use your device copy menu."}}$("copy-selection").onclick=()=>copy(selected);$("copy-all").onclick=()=>copy($("out").value);$("save").onclick=()=>{const f=file.files[0],name=f?f.name.replace(/\.[^.]+$/,""):"document",u=URL.createObjectURL(new Blob([$("out").value],{type:"text/plain"})),a=document.createElement("a");a.href=u;a.download=name+".txt";a.click();setTimeout(()=>URL.revokeObjectURL(u),1000)}})();</script></body>');
